# -*- coding: utf-8 -*-
from parts import *
def hero(crumb, h1, lead, aside, btn="Échanger sur vos enjeux"):
    return f'<section class="c-page-hero"><div class="c-container">{crumbs([("Accueil","/"),(crumb,None)])}<div class="c-hero-grid"><div class="c-hero-text"><h1 class="c-h1-page">{h1}</h1><p class="c-lead">{lead}</p><a href="#contact" class="c-btn">{btn}</a></div>{aside}</div></div></section>'
def aside(blocks):
    s='<div class="c-aside">'
    for t,items in blocks:
        s+=f'<p class="c-aside-title">{t}</p><ul class="c-aside-list">'+''.join(f'<li class="c-aside-item">{i}</li>' for i in items)+'</ul>'
    return s+'</div>'
def faq(title, qs, alt=False):
    cls="c-section-alt" if alt else "c-section"
    items=''.join(f'<div class="c-faq-item"><h3 class="c-faq-q">{q}</h3><p class="c-faq-a">{a}</p></div>' for q,a in qs)
    return f'<section class="{cls}"><div class="c-container"><h2 class="c-h2">{title}</h2><div class="c-faq">{items}</div></div></section>'
def ul(items): return '<ul class="c-list">'+''.join(f'<li class="c-list-item">{i}</li>' for i in items)+'</ul>'

CONSEIL_FAQ=[("Peut-on commencer par un audit ponctuel ?","Oui. Un diagnostic court suffit souvent pour dégager les priorités, avant de décider de la suite."),("Je n'ai pas d'équipe commerciale, est-ce utile ?","Oui. Si vous vendez vous-même, le plan est construit autour du temps que vous pouvez réellement y consacrer chaque semaine."),("Travaillez-vous hors d'Aix-en-Provence ?","Oui, à Marseille, dans les Bouches-du-Rhône et en région PACA.")]
CONSEIL='<main class="c-main">'+hero("Conseil commercial","Conseil commercial à Aix-en-Provence pour TPE et PME","J'aide les dirigeants à poser clairement quoi vendre, à qui, avec quel argument et dans quel ordre. Pour que le développement commercial suive un plan que vous pouvez tenir avec l'équipe que vous avez.",aside([("Pour qui",["Dirigeants de TPE et PME qui vendent à d'autres entreprises","Indépendants qui veulent sortir du bouche-à-oreille seul"]),("Ce que vous avez à la fin",["Vos priorités commerciales, écrites","Un plan d'action avec des échéances","Trois ou quatre indicateurs à suivre"])]))+'''<section class="c-section"><div class="c-container"><div class="c-two-col"><h2 class="c-h2">Une bonne offre ne suffit pas à vendre régulièrement</h2><div class="c-col"><p class="c-p">Beaucoup d'entreprises ont des clients satisfaits et un chiffre d'affaires en dents de scie. L'offre est rarement en cause. Le plus souvent, trop de canaux sont ouverts en même temps, le message change selon l'interlocuteur et les relances se font quand on y pense.</p><p class="c-p">Je repars de ce qui existe, je garde ce qui fonctionne et je transforme le reste en actions datées.</p></div></div></div></section><section class="c-section-alt"><div class="c-container"><div class="c-two-col"><div class="c-col"><h2 class="c-h2">Ce que la mission peut couvrir</h2>'''+ul(["Analyse de votre fonctionnement commercial actuel","Choix des cibles prioritaires","Travail de l'offre et de l'argumentaire","Organisation des canaux de prospection","Plan d'action daté","Suivi des prospects et des opportunités","Indicateurs de pilotage"])+'''</div><div class="c-col"><h3 class="c-h3">Cadrage seul ou mise en œuvre</h3><p class="c-p">On peut s'arrêter au diagnostic et au plan. Si vous le souhaitez, je reste pour la suite : CRM, supports de vente, landing page, campagnes, organisation des relances.</p><h3 class="c-h3">À votre échelle</h3><p class="c-p">Pas de tableau de bord à quarante lignes ni de réunion hebdomadaire en plus. Des décisions simples et des responsabilités claires.</p></div></div></div></section>'''+faq("Questions fréquentes sur le conseil commercial",CONSEIL_FAQ)+'</main>'+CONTACT+related("Aller plus loin",[("Marketing BtoB","/marketing-btob-aix-en-provence"),("Acquisition BtoB","/acquisition-btob-aix-en-provence"),("CRM et organisation commerciale","/crm-organisation-commerciale-aix-en-provence"),("Guide : structurer le développement commercial","/structurer-developpement-commercial-pme")])

MARKETING_FAQ=[("Connect est-il une agence marketing ?","Non. Je travaille à la jonction du conseil commercial et du marketing : chaque action marketing sert un objectif de vente."),("Pouvez-vous reprendre une landing page existante ?","Oui. Le message, la structure, les appels à l'action, le formulaire et la cohérence avec la campagne qui amène les visiteurs."),("Travaillez-vous le référencement local ?","Oui, quand la recherche locale compte pour votre activité, notamment autour d'Aix-en-Provence, de Marseille et dans les Bouches-du-Rhône.")]
MARKETING='<main class="c-main">'+hero("Marketing BtoB","Marketing BtoB à Aix-en-Provence pour TPE et PME","J'aide les entreprises qui vendent à d'autres entreprises à attirer des prospects qui correspondent à leur offre, puis à transformer cet intérêt en demandes de contact.",aside([("Ce que je regarde en premier",["Votre cible et la façon dont elle décide","Le chemin entre la première visite et la prise de contact","Les pages qui doivent convertir"])]))+'''<section class="c-section-alt"><div class="c-container"><div class="c-two-col"><h2 class="c-h2">En BtoB, personne ne signe au premier clic</h2><div class="c-col"><p class="c-p">Un prospect visite plusieurs pages, compare, revient quelques jours ou quelques semaines plus tard. Chaque action marketing doit l'aider à passer l'étape suivante : vous découvrir, s'intéresser, vous contacter, être convaincu.</p><p class="c-p">Je pars donc du besoin commercial. Les canaux, les contenus et les supports se choisissent ensuite, en fonction de votre cible et de votre offre.</p></div></div></div></section><section class="c-section"><div class="c-container"><div class="c-two-col"><div class="c-col"><h2 class="c-h2">Ce que je peux prendre en charge</h2>'''+ul(["Stratégie d'acquisition BtoB","Analyse du parcours de vos prospects","Création ou reprise de landing pages","Messages et contenus orientés conversion","Campagnes commerciales et marketing","Visibilité locale et référencement","Lien entre marketing, CRM et suivi commercial"])+'''</div><div class="c-example"><p class="c-aside-title">Un exemple</p><p class="c-example-text">Fer de Lance Tattoo, studio de tatouage. Après la refonte du site et le travail sur le référencement local, la cliente constate environ 30 % de chiffre d'affaires en plus et davantage de demandes de devis.</p><h3 class="c-h3">Ce que je mesure</h3><p class="c-p">Les demandes entrantes et leur qualité, le taux de conversion des pages, l'origine des opportunités. Le nombre de visites reste un indicateur parmi d'autres.</p></div></div></div></section>'''+faq("Questions fréquentes sur le marketing BtoB",MARKETING_FAQ,True)+'</main>'+CONTACT+related("Aller plus loin",[("Conseil commercial","/conseil-commercial-aix-en-provence"),("Acquisition BtoB","/acquisition-btob-aix-en-provence"),("CRM et organisation commerciale","/crm-organisation-commerciale-aix-en-provence"),("Guide marketing BtoB","/marketing-btob-tpe-pme"),("Cas client Fer de Lance","/cas-client-fer-de-lance")])

ACQ_FAQ=[("Faites-vous de la génération de leads ?","Oui, si elle correspond à votre cible, à votre offre et à votre capacité à suivre les demandes."),("Faut-il forcément de la publicité payante ?","Non. La prospection, le contenu, le référencement, le réseau et les partenariats suffisent souvent pour commencer."),("Pouvez-vous organiser le suivi des leads ?","Oui : pipeline, étapes, relances et informations utiles dans le CRM.")]
ACQ='<main class="c-main">'+hero("Acquisition BtoB","Acquisition BtoB et prospection à Aix-en-Provence","Je vous aide à choisir les bons canaux, à cibler les entreprises qui comptent pour vous et à traiter chaque demande jusqu'au rendez-vous.",aside([("Ce que vous avez à la fin",["Une liste de cibles priorisée","Deux ou trois canaux choisis et testés","Un circuit clair pour traiter et relancer les leads"])]))+'''<section class="c-section"><div class="c-container"><div class="c-two-col"><h2 class="c-h2">Un lead ne vaut rien si personne ne le rappelle</h2><div class="c-col"><p class="c-p">Une demande a de la valeur si elle vient d'une cible pertinente, si elle est traitée vite et si l'entreprise sait quoi en faire. Une campagne sans suivi, ou un formulaire qui reste sans réponse, coûte du temps et du budget.</p><p class="c-p">Pour une petite structure, deux ou trois canaux bien exploités rapportent plus qu'une dizaine ouverts en même temps. On les garde assez longtemps pour mesurer ce qu'ils donnent.</p></div></div></div></section><section class="c-section-dark"><div class="c-container"><div class="c-about"><p class="c-eyebrow-light">Avis client</p><p class="c-quote-light">« Depuis que Valentin a rejoint notre système d'acquisition, nos résultats ont grandement progressé. »</p><p class="c-p-light">Yoan Bouc, dirigeant d'Insight to Sell, avis Google</p></div></div></section><section class="c-section"><div class="c-container"><div class="c-two-col"><div class="c-col"><h2 class="c-h2">Les leviers possibles</h2>'''+ul(["Prospection BtoB ciblée","Campagnes d'acquisition","Landing pages et formulaires","Contenus qui rassurent ou qualifient","Réseau, partenariats et recommandations","Référencement et visibilité locale, si c'est pertinent","Organisation du CRM et des relances"])+'''</div><div class="c-col"><h3 class="c-h3">Après le formulaire, le travail continue</h3><p class="c-p">Le délai de réponse, le message de relance, les informations collectées et le suivi dans le CRM décident si une demande devient une vraie opportunité. Je m'occupe aussi de cette partie.</p></div></div></div></section>'''+faq("Questions fréquentes sur l'acquisition BtoB",ACQ_FAQ,True)+'</main>'+CONTACT+related("Aller plus loin",[("Conseil commercial","/conseil-commercial-aix-en-provence"),("Marketing BtoB","/marketing-btob-aix-en-provence"),("CRM et organisation commerciale","/crm-organisation-commerciale-aix-en-provence"),("Guide marketing BtoB","/marketing-btob-tpe-pme")])

CRM_FAQ=[("Peut-on garder notre CRM actuel ?","Oui. Si l'outil convient, je l'améliore plutôt que de le remplacer."),("Faut-il tout automatiser ?","Non. Une automatisation se justifie quand elle simplifie le suivi. Si elle rend le processus opaque, je la déconseille."),("Est-ce adapté à une petite équipe ?","Oui, le dispositif est dimensionné selon votre volume d'affaires et vos habitudes.")]
CRM='<main class="c-main">'+hero("CRM et organisation commerciale","CRM et organisation commerciale à Aix-en-Provence","Je mets en place un suivi commercial simple : vos prospects au même endroit, des étapes claires et des relances qui ne dépendent plus de la mémoire de chacun.",aside([("C'est le moment si",["Vos prospects sont répartis entre plusieurs fichiers","Vous ne savez pas dire combien d'affaires sont en cours","Des relances passent à la trappe"])]))+'''<section class="c-section"><div class="c-container"><div class="c-two-col"><h2 class="c-h2">Un CRM utile, c'est celui que l'équipe ouvre vraiment</h2><div class="c-col"><p class="c-p">Le manque d'outil est rarement le vrai problème. Plus souvent, le CRM est trop compliqué, les informations sont éparpillées, les étapes sont floues et les relances se font de tête.</p><p class="c-p">Je commence par le processus : comment une affaire avance chez vous, du premier contact à la décision. L'outil vient ensuite.</p></div></div></div></section><section class="c-section-alt"><div class="c-container"><h2 class="c-h2">Les étapes que l'on pose ensemble</h2><p class="c-sub">Un exemple de pipeline. Les étapes s'adaptent à votre cycle de vente.</p><ol class="c-pipeline"><li class="c-pipe-step">Premier contact</li><li class="c-pipe-step">Qualification</li><li class="c-pipe-step">Rendez-vous</li><li class="c-pipe-step">Proposition</li><li class="c-pipe-step">Relance</li><li class="c-pipe-step">Décision</li></ol></div></section><section class="c-section"><div class="c-container"><div class="c-two-col"><div class="c-col"><h2 class="c-h2">Ce qui peut être structuré</h2>'''+ul(["Organisation des prospects et des clients","Création ou simplification du pipeline","Règles de saisie","Suivi des prochaines actions","Relances et rappels","Quelques automatisations, si elles simplifient","Tableau de bord et indicateurs"])+'''</div><div class="c-col"><h3 class="c-h3">Piloter sans y passer ses soirées</h3><p class="c-p">Avec des données propres, vous voyez d'un coup d'oeil le nombre d'affaires en cours, les relances du jour et l'étape où les dossiers ralentissent.</p></div></div></div></section>'''+faq("Questions fréquentes sur le CRM",CRM_FAQ,True)+'</main>'+CONTACT+related("Aller plus loin",[("Conseil commercial","/conseil-commercial-aix-en-provence"),("Marketing BtoB","/marketing-btob-aix-en-provence"),("Acquisition BtoB","/acquisition-btob-aix-en-provence"),("Guide : structurer le développement commercial","/structurer-developpement-commercial-pme")])
